CREATE TYPE "user_status" AS ENUM ('active','suspended','deleted');
CREATE TYPE "connection_status" AS ENUM ('connected','reauth_required','revoked');
CREATE TYPE "device_status" AS ENUM ('pending','active','revoked');
CREATE TYPE "browser_session_status" AS ENUM ('provisioning','active','auth_required','expired','revoked','failed');
CREATE TYPE "control_lease_status" AS ENUM ('pending','active','released','expired','revoked');
CREATE TYPE "browser_runtime_status" AS ENUM ('provisioning','running','stopped','failed','revoked');
CREATE TYPE "sync_job_status" AS ENUM ('queued','leased','running','succeeded','failed','cancelled');
CREATE TYPE "operation_status" AS ENUM ('previewed','confirmed','dispatched','succeeded','failed','unknown','cancelled');
CREATE TYPE "planner_source" AS ENUM ('app','canvas');
CREATE TYPE "planner_status" AS ENUM ('todo','in_progress','completed','cancelled');

CREATE TABLE "users" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "clerk_user_id" text NOT NULL UNIQUE, "primary_email" text, "display_name" text, "avatar_url" text, "status" user_status NOT NULL DEFAULT 'active', "last_seen_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "user_preferences" ("owner_id" uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, "timezone" text NOT NULL DEFAULT 'UTC', "theme" text NOT NULL DEFAULT 'system', "week_starts_on" integer NOT NULL DEFAULT 0 CHECK (week_starts_on BETWEEN 0 AND 6), "notifications" jsonb NOT NULL DEFAULT '{}', "retention" jsonb NOT NULL DEFAULT '{}', "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "canvas_accounts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "canvas_base_url" text NOT NULL, "canvas_user_id" text NOT NULL, "display_name" text, "avatar_url" text, "locale" text, "timezone" text, "status" connection_status NOT NULL DEFAULT 'connected', "last_synced_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,id), UNIQUE(owner_id,canvas_base_url,canvas_user_id));
CREATE TABLE "hosted_browser_profiles" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "canvas_account_id" uuid, "provider" text NOT NULL, "provider_profile_ref" text NOT NULL, "canvas_origin" text NOT NULL, "region" text, "status" text NOT NULL DEFAULT 'active', "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,id), UNIQUE(provider,provider_profile_ref), CONSTRAINT hosted_browser_profiles_tenant_account_fk FOREIGN KEY(owner_id,canvas_account_id) REFERENCES canvas_accounts(owner_id,id) ON DELETE CASCADE);
CREATE TABLE "hosted_browser_sessions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "profile_id" uuid NOT NULL, "canvas_account_id" uuid, "provider" text NOT NULL, "provider_session_ref" text NOT NULL, "provider_container_ref" text, "status" browser_session_status NOT NULL DEFAULT 'provisioning', "encrypted_state_ciphertext" text, "encrypted_state_nonce" text, "wrapped_data_key" text, "key_version" integer, "provider_secret_ref" text, "consent_version" text NOT NULL, "consented_at" timestamptz NOT NULL, "consent_ip_hash" text, "last_auth_check_at" timestamptz, "expires_at" timestamptz, "revoked_at" timestamptz, "failure_code" text, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,id), UNIQUE(provider,provider_session_ref), CONSTRAINT hosted_browser_sessions_tenant_profile_fk FOREIGN KEY(owner_id,profile_id) REFERENCES hosted_browser_profiles(owner_id,id) ON DELETE CASCADE, CONSTRAINT hosted_browser_sessions_tenant_account_fk FOREIGN KEY(owner_id,canvas_account_id) REFERENCES canvas_accounts(owner_id,id) ON DELETE CASCADE, CONSTRAINT hosted_browser_sessions_secret_storage_check CHECK (provider_secret_ref IS NOT NULL OR (encrypted_state_ciphertext IS NOT NULL AND encrypted_state_nonce IS NOT NULL AND wrapped_data_key IS NOT NULL AND key_version IS NOT NULL)));
ALTER TABLE "hosted_browser_sessions" ADD COLUMN "canvas_external_account_id" text;
CREATE TABLE "remote_browser_control_leases" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "session_id" uuid NOT NULL, "controller_type" text NOT NULL, "controller_id" text NOT NULL, "lease_token_hash" text NOT NULL, "takeover_token_ref" text, "status" control_lease_status NOT NULL DEFAULT 'pending', "lease_expires_at" timestamptz NOT NULL, "activated_at" timestamptz, "released_at" timestamptz, "revoked_at" timestamptz, "revoke_reason" text, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,id), CONSTRAINT remote_browser_control_leases_tenant_session_fk FOREIGN KEY(owner_id,session_id) REFERENCES hosted_browser_sessions(owner_id,id) ON DELETE CASCADE);
CREATE TABLE "self_hosted_browser_instances" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "session_id" uuid NOT NULL, "runtime_id" text NOT NULL UNIQUE, "container_ref" text NOT NULL, "profile_volume_ref" text, "cdp_endpoint_ref" text, "status" browser_runtime_status NOT NULL DEFAULT 'provisioning', "resource_limits" jsonb NOT NULL DEFAULT '{}', "last_heartbeat_at" timestamptz, "stopped_at" timestamptz, "revoked_at" timestamptz, "failure_code" text, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,id), UNIQUE(owner_id,session_id), CONSTRAINT self_hosted_browser_instances_tenant_session_fk FOREIGN KEY(owner_id,session_id) REFERENCES hosted_browser_sessions(owner_id,id) ON DELETE CASCADE);
CREATE TABLE "extension_devices" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "canvas_account_id" uuid, "public_id" text NOT NULL UNIQUE, "name" text NOT NULL DEFAULT 'Canvas browser', "credential_hash" text, "credential_prefix" text, "scopes" text[] NOT NULL DEFAULT ARRAY[]::text[], "status" device_status NOT NULL DEFAULT 'pending', "paired_at" timestamptz, "last_seen_at" timestamptz, "revoked_at" timestamptz, "user_agent_summary" text, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,id), CONSTRAINT extension_devices_tenant_account_fk FOREIGN KEY(owner_id,canvas_account_id) REFERENCES canvas_accounts(owner_id,id) ON DELETE CASCADE);
CREATE TABLE "pairing_codes" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "code_hash" text NOT NULL UNIQUE, "expires_at" timestamptz NOT NULL, "claimed_at" timestamptz, "claimed_device_id" uuid, "attempts" integer NOT NULL DEFAULT 0, "created_at" timestamptz NOT NULL DEFAULT now(), CONSTRAINT pairing_codes_tenant_device_fk FOREIGN KEY(owner_id,claimed_device_id) REFERENCES extension_devices(owner_id,id));
CREATE TABLE "courses" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "canvas_account_id" uuid NOT NULL, "canvas_course_id" text NOT NULL, "name" text NOT NULL, "course_code" text, "term_name" text, "workflow_state" text, "start_at" timestamptz, "end_at" timestamptz, "current_score" numeric, "current_grade" text, "image_url" text, "favorite" boolean NOT NULL DEFAULT false, "source_updated_at" timestamptz, "synced_at" timestamptz NOT NULL DEFAULT now(), "deleted_at" timestamptz, "source_payload" jsonb NOT NULL DEFAULT '{}', "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,id), UNIQUE(canvas_account_id,canvas_course_id), CONSTRAINT courses_tenant_account_fk FOREIGN KEY(owner_id,canvas_account_id) REFERENCES canvas_accounts(owner_id,id) ON DELETE CASCADE);
CREATE TABLE "assignments" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "course_id" uuid NOT NULL, "canvas_assignment_id" text NOT NULL, "name" text NOT NULL, "description_html" text, "due_at" timestamptz, "unlock_at" timestamptz, "lock_at" timestamptz, "points_possible" numeric, "submission_types" text[] NOT NULL DEFAULT ARRAY[]::text[], "workflow_state" text, "grading_type" text, "position" integer, "source_updated_at" timestamptz, "synced_at" timestamptz NOT NULL DEFAULT now(), "deleted_at" timestamptz, "source_payload" jsonb NOT NULL DEFAULT '{}', "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,id), UNIQUE(course_id,canvas_assignment_id), CONSTRAINT assignments_tenant_course_fk FOREIGN KEY(owner_id,course_id) REFERENCES courses(owner_id,id) ON DELETE CASCADE);
CREATE TABLE "submissions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "assignment_id" uuid NOT NULL, "canvas_submission_id" text, "attempt" integer NOT NULL DEFAULT 0, "state" text, "submitted_at" timestamptz, "graded_at" timestamptz, "score" numeric, "grade" text, "late" boolean NOT NULL DEFAULT false, "missing" boolean NOT NULL DEFAULT false, "excused" boolean NOT NULL DEFAULT false, "source_updated_at" timestamptz, "synced_at" timestamptz NOT NULL DEFAULT now(), "source_payload" jsonb NOT NULL DEFAULT '{}', "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(assignment_id,attempt), CONSTRAINT submissions_tenant_assignment_fk FOREIGN KEY(owner_id,assignment_id) REFERENCES assignments(owner_id,id) ON DELETE CASCADE);
CREATE TABLE "planner_items" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "canvas_account_id" uuid, "course_id" uuid, "assignment_id" uuid, "source" planner_source NOT NULL DEFAULT 'app', "canvas_item_type" text, "canvas_item_id" text, "kind" text NOT NULL DEFAULT 'task', "title" text NOT NULL, "notes" text, "starts_at" timestamptz, "due_at" timestamptz, "completed_at" timestamptz, "status" planner_status NOT NULL DEFAULT 'todo', "priority" integer NOT NULL DEFAULT 0, "recurrence" jsonb, "deleted_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), CONSTRAINT planner_items_tenant_account_fk FOREIGN KEY(owner_id,canvas_account_id) REFERENCES canvas_accounts(owner_id,id) ON DELETE CASCADE, CONSTRAINT planner_items_tenant_course_fk FOREIGN KEY(owner_id,course_id) REFERENCES courses(owner_id,id) ON DELETE CASCADE, CONSTRAINT planner_items_tenant_assignment_fk FOREIGN KEY(owner_id,assignment_id) REFERENCES assignments(owner_id,id) ON DELETE CASCADE);
CREATE TABLE "notes" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "course_id" uuid, "assignment_id" uuid, "title" text NOT NULL, "body_md" text NOT NULL DEFAULT '', "deleted_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), CONSTRAINT notes_tenant_course_fk FOREIGN KEY(owner_id,course_id) REFERENCES courses(owner_id,id) ON DELETE CASCADE, CONSTRAINT notes_tenant_assignment_fk FOREIGN KEY(owner_id,assignment_id) REFERENCES assignments(owner_id,id) ON DELETE CASCADE);
CREATE TABLE "conversations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "canvas_account_id" uuid NOT NULL, "course_id" uuid, "canvas_conversation_id" text NOT NULL, "subject" text, "workflow_state" text, "last_message_at" timestamptz, "message_count" integer NOT NULL DEFAULT 0, "starred" boolean NOT NULL DEFAULT false, "participants" jsonb NOT NULL DEFAULT '[]', "source_payload" jsonb NOT NULL DEFAULT '{}', "synced_at" timestamptz NOT NULL DEFAULT now(), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,id), UNIQUE(canvas_account_id,canvas_conversation_id), CONSTRAINT conversations_tenant_account_fk FOREIGN KEY(owner_id,canvas_account_id) REFERENCES canvas_accounts(owner_id,id) ON DELETE CASCADE, CONSTRAINT conversations_tenant_course_fk FOREIGN KEY(owner_id,course_id) REFERENCES courses(owner_id,id));
CREATE TABLE "conversation_messages" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "conversation_id" uuid NOT NULL, "canvas_message_id" text NOT NULL, "author_canvas_id" text, "author_name" text, "body_html" text, "sent_at" timestamptz NOT NULL, "attachments" jsonb NOT NULL DEFAULT '[]', "source_payload" jsonb NOT NULL DEFAULT '{}', "created_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(conversation_id,canvas_message_id), CONSTRAINT conversation_messages_tenant_conversation_fk FOREIGN KEY(owner_id,conversation_id) REFERENCES conversations(owner_id,id) ON DELETE CASCADE);
CREATE TABLE "sync_cursors" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "canvas_account_id" uuid NOT NULL, "resource_type" text NOT NULL, "scope_key" text NOT NULL DEFAULT '', "cursor" jsonb, "etag" text, "last_success_at" timestamptz, "last_attempt_at" timestamptz, "consecutive_failures" integer NOT NULL DEFAULT 0, "last_error_code" text, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(canvas_account_id,resource_type,scope_key), CONSTRAINT sync_cursors_tenant_account_fk FOREIGN KEY(owner_id,canvas_account_id) REFERENCES canvas_accounts(owner_id,id) ON DELETE CASCADE);
CREATE TABLE "sync_jobs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "canvas_account_id" uuid NOT NULL, "device_id" uuid, "kind" text NOT NULL, "scope" jsonb NOT NULL DEFAULT '{}', "status" sync_job_status NOT NULL DEFAULT 'queued', "priority" integer NOT NULL DEFAULT 0, "attempt" integer NOT NULL DEFAULT 0, "max_attempts" integer NOT NULL DEFAULT 5, "run_after" timestamptz NOT NULL DEFAULT now(), "lease_owner" text, "lease_expires_at" timestamptz, "started_at" timestamptz, "finished_at" timestamptz, "error_code" text, "error_message" text, "stats" jsonb NOT NULL DEFAULT '{}', "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), CONSTRAINT sync_jobs_tenant_account_fk FOREIGN KEY(owner_id,canvas_account_id) REFERENCES canvas_accounts(owner_id,id) ON DELETE CASCADE, CONSTRAINT sync_jobs_tenant_device_fk FOREIGN KEY(owner_id,device_id) REFERENCES extension_devices(owner_id,id));
CREATE TABLE "operation_previews" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "canvas_account_id" uuid, "action" text NOT NULL, "request_digest" text NOT NULL, "preview" jsonb NOT NULL, "expires_at" timestamptz NOT NULL, "confirmed_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,id), CONSTRAINT operation_previews_tenant_account_fk FOREIGN KEY(owner_id,canvas_account_id) REFERENCES canvas_accounts(owner_id,id) ON DELETE CASCADE);
CREATE TABLE "canvas_operations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "canvas_account_id" uuid, "device_id" uuid, "preview_id" uuid, "action" text NOT NULL, "method" text NOT NULL, "canvas_path" text NOT NULL, "request_redacted" jsonb NOT NULL DEFAULT '{}', "status" operation_status NOT NULL DEFAULT 'previewed', "idempotency_key" text NOT NULL, "response_status" integer, "response_redacted" jsonb, "dispatched_at" timestamptz, "completed_at" timestamptz, "error_code" text, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,id), UNIQUE(owner_id,idempotency_key), CONSTRAINT canvas_operations_tenant_account_fk FOREIGN KEY(owner_id,canvas_account_id) REFERENCES canvas_accounts(owner_id,id) ON DELETE CASCADE, CONSTRAINT canvas_operations_tenant_device_fk FOREIGN KEY(owner_id,device_id) REFERENCES extension_devices(owner_id,id), CONSTRAINT canvas_operations_tenant_preview_fk FOREIGN KEY(owner_id,preview_id) REFERENCES operation_previews(owner_id,id));
CREATE TABLE "idempotency_keys" ("owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "key" text NOT NULL, "request_hash" text NOT NULL, "operation_id" uuid, "state" text NOT NULL DEFAULT 'processing', "response_status" integer, "response_body_redacted" jsonb, "locked_until" timestamptz, "expires_at" timestamptz NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(owner_id,key), CONSTRAINT idempotency_keys_tenant_operation_fk FOREIGN KEY(owner_id,operation_id) REFERENCES canvas_operations(owner_id,id) ON DELETE CASCADE);
CREATE TABLE "audit_events" ("id" bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, "owner_id" uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, "actor_clerk_user_id" text, "actor_type" text NOT NULL, "actor_device_id" uuid, "action" text NOT NULL, "target_type" text, "target_id" text, "outcome" text NOT NULL, "request_id" text, "ip_hash" text, "user_agent_summary" text, "metadata_redacted" jsonb NOT NULL DEFAULT '{}', "occurred_at" timestamptz NOT NULL DEFAULT now(), CONSTRAINT audit_events_tenant_device_fk FOREIGN KEY(owner_id,actor_device_id) REFERENCES extension_devices(owner_id,id));

CREATE INDEX canvas_accounts_owner_idx ON canvas_accounts(owner_id);
CREATE INDEX hosted_browser_profiles_owner_idx ON hosted_browser_profiles(owner_id);
CREATE INDEX hosted_browser_sessions_owner_status_idx ON hosted_browser_sessions(owner_id,status);
CREATE INDEX hosted_browser_sessions_expiry_idx ON hosted_browser_sessions(expires_at);
CREATE INDEX remote_browser_control_leases_owner_session_idx ON remote_browser_control_leases(owner_id,session_id,status);
CREATE INDEX remote_browser_control_leases_expiry_idx ON remote_browser_control_leases(lease_expires_at);
CREATE INDEX self_hosted_browser_instances_owner_status_idx ON self_hosted_browser_instances(owner_id,status);
CREATE INDEX extension_devices_owner_status_idx ON extension_devices(owner_id,status);
CREATE INDEX pairing_codes_expiry_idx ON pairing_codes(expires_at);
CREATE INDEX courses_owner_active_idx ON courses(owner_id,deleted_at);
CREATE INDEX assignments_owner_due_idx ON assignments(owner_id,due_at);
CREATE INDEX submissions_owner_state_idx ON submissions(owner_id,state);
CREATE INDEX planner_items_owner_due_idx ON planner_items(owner_id,status,due_at);
CREATE UNIQUE INDEX planner_items_canvas_identity_unique ON planner_items(canvas_account_id,canvas_item_type,canvas_item_id) WHERE source='canvas';
CREATE INDEX notes_owner_updated_idx ON notes(owner_id,updated_at);
CREATE INDEX conversations_owner_recent_idx ON conversations(owner_id,last_message_at DESC);
CREATE INDEX conversation_messages_thread_time_idx ON conversation_messages(conversation_id,sent_at);
CREATE INDEX sync_jobs_claim_idx ON sync_jobs(status,run_after,priority DESC);
CREATE INDEX sync_jobs_owner_status_idx ON sync_jobs(owner_id,status);
CREATE INDEX operation_previews_expiry_idx ON operation_previews(expires_at);
CREATE INDEX canvas_operations_owner_recent_idx ON canvas_operations(owner_id,created_at DESC);
CREATE INDEX idempotency_keys_expiry_idx ON idempotency_keys(expires_at);
CREATE INDEX audit_events_owner_time_idx ON audit_events(owner_id,occurred_at DESC);

-- Defense in depth: application transactions set `SET LOCAL app.user_id = '<uuid>'`.
ALTER TABLE "remote_browser_control_leases" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "remote_browser_control_leases" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "remote_browser_control_leases" USING (owner_id = nullif(current_setting('app.user_id', true), '')::uuid) WITH CHECK (owner_id = nullif(current_setting('app.user_id', true), '')::uuid);
ALTER TABLE "self_hosted_browser_instances" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "self_hosted_browser_instances" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "self_hosted_browser_instances" USING (owner_id = nullif(current_setting('app.user_id', true), '')::uuid) WITH CHECK (owner_id = nullif(current_setting('app.user_id', true), '')::uuid);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['user_preferences','canvas_accounts','hosted_browser_profiles','hosted_browser_sessions','extension_devices','pairing_codes','courses','assignments','submissions','planner_items','notes','conversations','conversation_messages','sync_cursors','sync_jobs','operation_previews','canvas_operations','idempotency_keys','audit_events'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t); EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (owner_id = nullif(current_setting(''app.user_id'', true), '''')::uuid) WITH CHECK (owner_id = nullif(current_setting(''app.user_id'', true), '''')::uuid)', t); END LOOP; END $$;
